<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Maintenance | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"></head><body>
<header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/maintenance">Maintenance</a><a href="/fleet/vehicles">Fleet</a></nav></header><main class="page-shell">
<section class="page-heading"><div><p class="eyebrow">Fleet operations</p><h1>Maintenance</h1><p>Signed in as <?= $e($user['email']) ?> (<?= $e($user['role']) ?>)</p></div><a class="button-link" href="/maintenance/due">Due report / CSV</a></section>
<?php if(!empty($notice)):?><p class="notice panel"><?= $e($notice) ?></p><?php endif;?>
<section class="panel"><h2>Due and due soon</h2><p>Default warning: <?= (int)$defaults['days'] ?> Manila days or <?= (int)$defaults['kilometers'] ?> km. A schedule override replaces its matching default.</p><div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Schedule</th><th>State</th><th>Next date</th><th>Next mileage</th><th>Current mileage</th><th>Effective warning</th></tr></thead><tbody><?php foreach($due as $row):?><tr><td><?= $e($row['plate_number'].' '.$row['make'].' '.$row['model']) ?></td><td><?= $e($row['schedule_name']) ?></td><td><?= $e($row['due_state']) ?></td><td><?= $e($row['next_due_date']??'—') ?></td><td><?= $e($row['next_due_mileage']??'—') ?></td><td><?= $e($row['current_mileage']) ?></td><td><?= (int)$row['effective_due_soon_days'] ?> days / <?= (int)$row['effective_due_soon_mileage'] ?> km</td></tr><?php endforeach;?><?php if(!$due):?><tr><td colspan="7">No schedules are due or within their warning window.</td></tr><?php endif;?></tbody></table></div></section>
<?php if(in_array($user['role'],['fleet_manager','system_admin'],true)):?><section class="panel"><h2>Create named schedule</h2><form method="post" action="/maintenance/schedules/create"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label>Vehicle<select name="vehicle_id" required><?php foreach($vehicles as $v):?><option value="<?= (int)$v['vehicle_id'] ?>"><?= $e($v['plate_number'].' '.$v['make'].' '.$v['model'].' — '.$v['current_status']) ?></option><?php endforeach;?></select></label><label>Schedule name<input name="schedule_name" maxlength="100" required placeholder="Oil change"></label><label>Time interval (days)<input type="number" name="interval_time_days" min="1"></label><label>Mileage interval (km)<input type="number" name="interval_mileage" min="1"></label><label>First due date (optional; defaults to today + interval)<input type="date" name="next_due_date"></label><label>First due mileage (optional; defaults to current mileage + interval)<input type="number" name="next_due_mileage" min="0"></label><label>Due-soon days override (blank inherits <?= (int)$defaults['days'] ?>)<input type="number" name="due_soon_days_override" min="1"></label><label>Due-soon km override (blank inherits <?= (int)$defaults['kilometers'] ?>)<input type="number" name="due_soon_mileage_override" min="1"></label><label>Reason<textarea name="reason" maxlength="500" required></textarea></label><button type="submit">Create schedule</button></form></section><?php endif;?>
<section class="panel"><h2>Schedules</h2><div class="table-wrap"><table><thead><tr><th>Vehicle / schedule</th><th>Intervals</th><th>Next due</th><th>Overrides</th><th>Status</th><th>History</th><?php if(in_array($user['role'],['fleet_manager','system_admin'],true)):?><th>Update</th><?php endif;?></tr></thead><tbody><?php foreach($schedules as $s):?><tr><td><?= $e($s['plate_number'].' '.$s['make'].' '.$s['model']) ?><br><?= $e($s['schedule_name']) ?></td><td><?= $s['interval_time_days']===null?'—':(int)$s['interval_time_days'].' days' ?> / <?= $s['interval_mileage']===null?'—':(int)$s['interval_mileage'].' km' ?></td><td><?= $e($s['next_due_date']??'—') ?> / <?= $e($s['next_due_mileage']??'—') ?></td><td><?= $s['due_soon_days_override']===null?'global':(int)$s['due_soon_days_override'].' days' ?> / <?= $s['due_soon_mileage_override']===null?'global':(int)$s['due_soon_mileage_override'].' km' ?></td><td><?= (int)$s['is_active']===1?'active':'retired' ?></td><td><a href="/maintenance/history?vehicle_id=<?= (int)$s['vehicle_id'] ?>">Vehicle history</a></td><?php if(in_array($user['role'],['fleet_manager','system_admin'],true)):?><td><details><summary>Edit</summary><form method="post" action="/maintenance/schedules/update"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="schedule_id" value="<?= (int)$s['schedule_id'] ?>"><input type="hidden" name="vehicle_id" value="<?= (int)$s['vehicle_id'] ?>"><label>Name<input name="schedule_name" value="<?= $e($s['schedule_name']) ?>" required></label><label>Days<input type="number" min="1" name="interval_time_days" value="<?= $e($s['interval_time_days']) ?>"></label><label>Km<input type="number" min="1" name="interval_mileage" value="<?= $e($s['interval_mileage']) ?>"></label><label>Due date<input type="date" name="next_due_date" value="<?= $e($s['next_due_date']) ?>"></label><label>Due km<input type="number" min="0" name="next_due_mileage" value="<?= $e($s['next_due_mileage']) ?>"></label><label>Due-soon days override<input type="number" min="1" name="due_soon_days_override" value="<?= $e($s['due_soon_days_override']) ?>"></label><label>Due-soon km override<input type="number" min="1" name="due_soon_mileage_override" value="<?= $e($s['due_soon_mileage_override']) ?>"></label><label><input type="checkbox" name="is_active" value="1"<?= (int)$s['is_active']===1?' checked':'' ?>> Active</label><label>Reason<textarea name="reason" required maxlength="500"></textarea></label><button>Save audited changes</button></form></details></td><?php endif;?></tr><?php endforeach;?><?php if(!$schedules):?><tr><td colspan="7">No maintenance schedules are configured.</td></tr><?php endif;?></tbody></table></div></section>
<?php if(in_array($user['role'],['mechanic','fleet_manager','system_admin'],true)):?><section class="panel"><h2>Start a service</h2><p><a class="button-link" href="/maintenance/service/new">Start service</a></p></section><?php endif;?>
<section class="panel"><h2>In-progress and recent services</h2><div class="table-wrap"><table><thead><tr><th>Started</th><th>Vehicle</th><th>Schedule</th><th>Title</th><th>Status</th><th>Total cost</th><th></th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><?= $e($s['started_at']) ?></td><td><?= $e($s['plate_number'].' '.$s['make'].' '.$s['model']) ?></td><td><?= $e($s['schedule_name']??'Corrective / unscheduled') ?></td><td><?= $e($s['title']) ?></td><td><?= $e($s['status']) ?></td><td><?= $e($s['total_cost']) ?></td><td><a href="/maintenance/service?service_id=<?= (int)$s['service_id'] ?>">Open</a></td></tr><?php endforeach;?><?php if(!$services):?><tr><td colspan="7">No service records yet.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><h2>Vehicle status reviews</h2><?php if(!$needsReview):?><p>No unresolved reviews.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Saved status</th><th>Service</th><th>Resolve</th></tr></thead><tbody><?php foreach($needsReview as $r):?><tr><td><?= $e($r['plate_number'].' '.$r['make'].' '.$r['model']) ?></td><td><?= $e($r['vehicle_status_before']) ?> (vehicle remains maintenance until resolved)</td><td><a href="/maintenance/service?service_id=<?= (int)$r['service_id'] ?>">#<?= (int)$r['service_id'] ?></a></td><td><?php if(in_array($user['role'],['fleet_manager','system_admin'],true)):?><form method="post" action="/maintenance/service/review"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="service_id" value="<?= (int)$r['service_id'] ?>"><select name="target_status" required><option value="">Choose…</option><?php foreach(['available','reserved','rented','cleaning','out_of_service'] as $state):?><option value="<?= $state ?>"><?= $state ?></option><?php endforeach;?></select><input name="reason" required maxlength="500" placeholder="Resolution reason"><button>Resolve</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
